import { friendlyHttpMessage, reportTechnical, UserFacingError } from './platform/errors';

export type School={id:string;name:string;code:string;status:'ACTIVE'|'SUSPENDED'|'DISABLED';logo_url?:string|null;email?:string|null;phone?:string|null;version:number};
export type PlatformLoginResult={access_token:string;token_type:'bearer';expires_in:number;scope:'PLATFORM';user:{id:string;email:string;full_name:string}};
export type SchoolLoginResult={access_token:string;token_type:'bearer';expires_in:number;scope:'SCHOOL';user:{id:string;email:string;full_name:string};school:{id:string;code:string;name:string};permissions:string[]};
export type ReadinessItem={code:string;label:string;state:'READY'|'TO_CONFIRM'|'TO_COMPLETE'|'NOT_APPLICABLE';detail:string;blocking_only_for:string[]};
export type SettingsOverview={school:{id:string;code:string;name:string;email?:string|null;phone?:string|null;logo_url?:string|null;address?:string|null;city?:string|null;province?:string|null;version:number};readiness:{percent:number;global_blocking:false;items:ReadinessItem[]};bootstrap?:{suggested_year_code?:string|null;internal_notifications_enabled:boolean;external_sms_enabled:boolean;version:number}|null};
export type AcademicYear={id:string;code:string;label:string;start_date:string;end_date:string;status:'PREPARED'|'ACTIVE'|'CLOSED'|'ARCHIVED';version:number};
export type SchoolSection={id:string;code:string;label:string;enabled:boolean;version:number};
export type SchoolClass={id:string;academic_year_id:string;section_id:string;option_id?:string|null;reference_code?:string|null;code:string;label:string;enabled:boolean;version:number;section_code?:string;section_label?:string;academic_year_code?:string;academic_year_label?:string};
export type FeeType={id:string;code:string;label:string;periodicity:'ONE_TIME'|'MONTHLY'|'PERIODIC'|'OPTIONAL';default_currency:'CDF'|'USD';regulatory:boolean;enabled:boolean;version:number};
export type Tariff={id:string;academic_year_id:string;fee_type_id:string;class_id?:string|null;section_id?:string|null;option_id?:string|null;currency:'CDF'|'USD';amount:string;billing_months:string[];enabled:boolean;version:number;fee_code?:string;fee_label?:string;class_label?:string|null;section_label?:string|null};
export type ReferenceCatalog={sections:{code:string;label:string;sort_order:number}[];classes:{code:string;section_code:string;label:string;sort_order:number}[];fee_types:{code:string;label:string;periodicity:FeeType['periodicity'];default_currency:'CDF'|'USD';sort_order:number}[]};

const API=import.meta.env.VITE_API_BASE_URL ?? '/api/v1';

async function errorDetail(r:Response, fallback:string){try{const b=await r.clone().json();reportTechnical(b,`HTTP ${r.status}`)}catch{/* réponse non JSON */}return r.status?friendlyHttpMessage(r.status):fallback}
function auth(token:string){return {'Authorization':`Bearer ${token}`,'Content-Type':'application/json'};}
function mutationHeaders(token:string,extra:Record<string,string>={}){return {...auth(token),'Idempotency-Key':crypto.randomUUID(),...extra}}

/** Platform accounts (option B): after the password the server asks for the second factor instead of opening a session. */
export type MfaStep={mfa_required:boolean;mfa_enrollment_required:boolean;mfa_token:string;expires_in:number;scope:'PLATFORM'|'SCHOOL';methods:('TOTP'|'RECOVERY_CODE')[]};
export function isMfaStep(r:unknown):r is MfaStep{return !!r&&typeof (r as {mfa_token?:unknown}).mfa_token==='string'}
export type MfaEnrollment={secret:string;otpauth_uri:string;qr_svg:string;account:string;issuer:string;digits:number;period:number};
export type PlatformMfaStatus={enrolled:boolean;method:'TOTP'|null;confirmed_at:string|null;recovery_codes_remaining:number;required:boolean;self_disable_allowed:boolean};
export class MfaError extends Error{constructor(public status:number,message:string){super(message)}}
async function mfaFailure(r:Response):Promise<never>{let detail='';try{const b=await r.json();if(typeof b?.detail==='string'&&b.detail.length<240)detail=b.detail}catch{/* non JSON */}throw new MfaError(r.status,detail||friendlyHttpMessage(r.status))}
async function mfaPost<T>(path:string,body:unknown):Promise<T>{const r=await fetch(`${API}/auth/mfa${path}`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)return mfaFailure(r);return r.json() as Promise<T>}
export function mfaVerify(mfa_token:string,input:{code?:string;recovery_code?:string}){return mfaPost<PlatformLoginResult&{recovery_codes_remaining?:number}>('/verify',{mfa_token,...input})}
export function mfaEnrollStart(mfa_token:string){return mfaPost<MfaEnrollment>('/enroll/start',{mfa_token})}
export function mfaEnrollConfirm(mfa_token:string,code:string){return mfaPost<PlatformLoginResult&{recovery_codes:string[]}>('/enroll/confirm',{mfa_token,code})}
export async function platformMfaStatus(token:string){return json<PlatformMfaStatus>(await fetch(`${API}/auth/platform/mfa`,{headers:auth(token),cache:'no-store'}),'État de la validation en deux étapes indisponible')}
export async function platformStepUp(token:string,code:string):Promise<{confirmed:boolean;valid_seconds:number}>{const r=await fetch(`${API}/auth/platform/mfa/step-up`,{method:'POST',headers:auth(token),body:JSON.stringify({code})});if(!r.ok)return mfaFailure(r);return r.json()}
export async function regenerateRecoveryCodes(token:string,code:string):Promise<{recovery_codes:string[]}>{const r=await fetch(`${API}/auth/platform/mfa/recovery-codes`,{method:'POST',headers:auth(token),body:JSON.stringify({code})});if(!r.ok)return mfaFailure(r);return r.json()}

/** N2: a temporary password set by a school must be replaced before any session (owner decision 2026-10-14). */
export type PasswordChangeStep={password_change_required:true;change_token:string;expires_in:number};
export function isPasswordChangeStep(r:unknown):r is PasswordChangeStep{return !!r&&(r as {password_change_required?:unknown}).password_change_required===true}
export async function firstPasswordChange(change_token:string,new_password:string):Promise<{changed:boolean}>{const r=await fetch(`${API}/auth/password/first-change`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({change_token,new_password})});if(!r.ok)return mfaFailure(r);return r.json()}

export async function loginPlatform(email:string,password:string):Promise<PlatformLoginResult|MfaStep>{
  const r=await fetch(`${API}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password,scope:'PLATFORM'})});
  if(!r.ok)throw new HttpLoginError(r.status);return r.json();
}
export type LoginContext={scope:'SCHOOL'|'PLATFORM';school_code:string|null;label:string};
export type AutoLoginResult=PlatformLoginResult|SchoolLoginResult|MfaStep|PasswordChangeStep|{choice_required:true;contexts:LoginContext[]};
/** Sign-in without a school code: the server determines the context after authentication. When the account
 * opens several spaces it returns the list and no session is created until the user picks one. */
export async function loginAuto(email:string,password:string):Promise<AutoLoginResult>{
  const r=await fetch(`${API}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password,scope:'AUTO'})});
  if(!r.ok)throw new HttpLoginError(r.status);return r.json();
}
export class HttpLoginError extends Error{constructor(public status:number){super(`HTTP ${status}`)}}
export async function loginSchool(email:string,password:string,schoolCode:string):Promise<SchoolLoginResult>{
  const r=await fetch(`${API}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password,scope:'SCHOOL',school_code:schoolCode})});
  if(!r.ok)throw new Error(await errorDetail(r,'Connexion école impossible'));return r.json();
}

