// Point 4B — Personnel
export type StaffCategory='ENSEIGNANT'|'ADMINISTRATIF'|'OUVRIER'|'AUTRE';
export type StaffStatus='ACTIVE'|'SUSPENDED'|'INACTIVE'|'LEFT';
export type StaffAssignment={id:string;function_id:string;function_code?:string;function_label?:string;function_category?:string;scope_type:'SCHOOL'|'SECTION'|'CLASS';scope_value?:string|null;section_label?:string|null;class_label?:string|null;is_primary:boolean;is_titular:boolean;titular_class_id?:string|null;titular_class_label?:string|null;start_date:string;end_date?:string|null;end_reason?:string|null;version:number};
export type StaffMember={id:string;school_id:string;employee_no:string;last_name:string;first_name?:string|null;middle_name?:string|null;gender?:'M'|'F'|'X'|null;birth_date?:string|null;phone?:string|null;email?:string|null;address?:string|null;category:StaffCategory;qualification?:string|null;specialty?:string|null;hire_date?:string|null;status:StaffStatus;exit_date?:string|null;exit_reason?:string|null;photo_url?:string|null;notes?:string|null;version:number;active_assignment_count?:number;has_linked_access?:boolean;staff_children_count?:number;assignments?:StaffAssignment[];history?:StaffHistoryEvent[];access_links?:StaffAccessLink[];staff_children?:StaffChildLink[]};
export type StaffFunction={id:string;code:string;label:string;category:string;enabled:boolean;sort_order:number;version:number};
export type StaffSummary={total:number;active:number;suspended:number;left:number;teachers:number;administrative:number;workers:number;other:number;active_assignments:number;linked_accounts:number;staff_children:number};
export type StaffDirectoryResponse={items:StaffMember[];total:number;limit:number;offset:number};
export type StaffHistoryEvent={id:string;staff_id:string;from_status?:string|null;to_status:string;effective_date:string;reason?:string|null;created_at:string;employee_no?:string;last_name?:string;first_name?:string|null;middle_name?:string|null};
export type StaffAccessLink={id:string;membership_id:string;active:boolean;membership_active?:boolean;email?:string|null;full_name?:string|null;linked_at:string;unlinked_at?:string|null;reason?:string|null};
export type StaffChildLink={id:string;student_id:string;relationship:string;active:boolean;responsibility_mode?:'FAMILY'|'PAYROLL'|'SCHOOL'|'THIRD_PARTY'|null;effective_from?:string|null;effective_until?:string|null;preference_version?:number|null};
