// Point 4D — Effectifs & dépôts (préservation Desktop)
export type EffectifsScope='ALL'|'MATERNELLE'|'PRIMAIRE'|'SECONDAIRE';
export type FGT={female:number;male:number;total:number};
export type EffectifsRow={section:string;label:string;code:string;enrolled:FGT;abandoned:FGT;transferred:FGT;active:FGT};
export type EffectifsOverview={active_students:number;active_girls:number;active_boys:number;active_classes:number;average_per_class:number;scope:EffectifsScope;academic_year:AcademicYear};
export type EffectifsCounts={items:EffectifsRow[];total:EffectifsRow;scope:EffectifsScope;group_by:'class'|'section'|'option';academic_year:AcademicYear};
export type EffectifsMovement={id:string;event_type:'ABANDON'|'TRANSFER'|'SUSPEND'|'REINTEGRATE'|'CLASS_CHANGE';effective_date:string;reason:string;destination?:string|null;matricule:string;student_name:string;gender?:string|null;section_label:string;class_label:string};
export type DepositRow={id:string;deposited_on:string;quantity:string;notes?:string|null;matricule:string;student_name:string;gender?:string|null;section_label:string;class_label:string;contribution_label:string;unit:string;recorded_by_name:string};
export type ContributionType={id:string;code:string;label:string;unit:string};
function qp(params:Record<string,string|number|undefined|null>){const q=new URLSearchParams();Object.entries(params).forEach(([k,v])=>{if(v!==undefined&&v!==null&&v!=='')q.set(k,String(v))});const s=q.toString();return s?`?${s}`:''}
export async function getEffectifsOverview(token:string,scope:EffectifsScope='ALL',yearId?:string):Promise<EffectifsOverview>{const r=await fetch(`${API}/effectifs/overview${qp({scope,year_id:yearId})}`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Effectifs indisponibles'));return r.json()}
export async function getEffectifsCounts(token:string,groupBy:'class'|'section'|'option',scope:EffectifsScope='ALL',yearId?:string):Promise<EffectifsCounts>{const r=await fetch(`${API}/effectifs/counts${qp({group_by:groupBy,scope,year_id:yearId})}`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Tableau des effectifs indisponible'));return r.json()}
export async function getEffectifsMovements(token:string,scope:EffectifsScope='ALL',input:{yearId?:string;classId?:string;eventType?:string;q?:string;limit?:number;offset?:number}={}):Promise<{items:EffectifsMovement[];total:number;limit:number;offset:number}>{const r=await fetch(`${API}/effectifs/movements${qp({scope,year_id:input.yearId,class_id:input.classId,event_type:input.eventType,q:input.q,limit:input.limit??50,offset:input.offset??0})}`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Mouvements indisponibles'));return r.json()}
export async function getDepositRegister(token:string,scope:EffectifsScope='ALL',input:{yearId?:string;classId?:string;contributionTypeId?:string;q?:string;limit?:number;offset?:number}={}):Promise<{items:DepositRow[];total:number;limit:number;offset:number}>{const r=await fetch(`${API}/effectifs/deposits${qp({scope,year_id:input.yearId,class_id:input.classId,contribution_type_id:input.contributionTypeId,q:input.q,limit:input.limit??100,offset:input.offset??0})}`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Registre des dépôts indisponible'));return r.json()}
export async function listContributionTypes(token:string):Promise<ContributionType[]>{const r=await fetch(`${API}/effectifs/contribution-types`,{headers:auth(token)});if(!r.ok)throw new Error(await errorDetail(r,'Contributions indisponibles'));return r.json()}
export async function recordMaterialDeposit(token:string,input:{enrollment_id:string;contribution_type_id:string;quantity:number;deposited_on?:string;notes?:string|null;scope?:EffectifsScope}){const r=await fetch(`${API}/effectifs/deposits`,{method:'POST',headers:mutationHeaders(token),body:JSON.stringify(input)});if(!r.ok)throw new Error(await errorDetail(r,'Dépôt impossible à enregistrer'));const b=await r.json();return b.body??b}
