async function json<T>(r:Response,fallback:string):Promise<T>{if(!r.ok)throw new UserFacingError(await serverDetail(r,fallback));return r.json() as Promise<T>}
/** Business refusals (409/422) carry a French, user-facing explanation from the server: show it. */
async function serverDetail(r:Response,fallback:string){try{const b=await r.clone().json();if((r.status===409||r.status===422||r.status===403)&&typeof b?.detail==='string'&&b.detail.length<240)return b.detail}catch{/* non JSON */}return friendlyHttpMessage(r.status)||fallback}

