export async function listPlatformSessions(token:string){return json<{items:DeviceSession[]}>(await fetch(`${API}/auth/platform/sessions`,{headers:auth(token),credentials:'include'}),'Sessions indisponibles')}
export async function revokePlatformSession(token:string,id:string){const r=await fetch(`${API}/auth/platform/sessions/${id}/revoke`,{method:'POST',headers:mutationHeaders(token)});if(!r.ok)throw new UserFacingError(await serverDetail(r,'Révocation impossible'))}
export async function changePlatformPassword(token:string,input:{current_password:string;new_password:string}){const r=await fetch(`${API}/auth/platform/password`,{method:'POST',headers:mutationHeaders(token),body:JSON.stringify(input)});if(!r.ok)throw new UserFacingError(await serverDetail(r,'Modification du mot de passe impossible'));return r.json()}
/** Signs this account out of every device (cookie-authenticated on the server, audited). */
export async function logoutAllDevices(){const r=await fetch(`${API}/auth/logout-all`,{method:'POST',credentials:'include'});if(!r.ok&&r.status!==401)throw new UserFacingError(await serverDetail(r,'Déconnexion impossible'))}
export async function revokeMySession(token:string,id:string){const r=await fetch(`${API}/auth/sessions/${id}/revoke`,{method:'POST',headers:mutationHeaders(token)});if(!r.ok)throw new UserFacingError(await serverDetail(r,'Révocation impossible'))}
export async function setupStatus(){return json<SetupStatus>(await fetch(`${API}/setup/status`,{cache:'no-store'}),'Statut indisponible')}
export async function createFirstManager(body:{full_name:string;email:string;password:string;setup_token?:string}){return json<{status:string;email:string}>(await fetch(`${API}/setup/first-manager`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),'Création impossible')}
export async function documentStorageStatus(token:string){return json<{available:boolean}>(await fetch(`${API}/documents/storage/status`,{headers:auth(token)}),'Stockage indisponible')}
export async function uploadSchoolLogo(token:string,file:File){return json<{sha256:string}>(await fetch(`${API}/documents/branding/logo`,{method:'PUT',headers:{'Authorization':`Bearer ${token}`,'Content-Type':file.type||'application/octet-stream'},body:file}),'Logo refusé')}
export async function schoolLogoBlob(token:string):Promise<Blob|null>{const r=await fetch(`${API}/documents/branding/logo`,{headers:{'Authorization':`Bearer ${token}`}});if(r.status===404)return null;if(!r.ok)throw new UserFacingError(friendlyHttpMessage(r.status));return r.blob()}
export async function documentHistory(token:string,offset=0){return json<{items:ArchivedDocument[];has_more:boolean;offset:number;limit:number;storage_available:boolean}>(await fetch(`${API}/documents/history${qp({offset,limit:50})}`,{headers:auth(token)}),'Historique indisponible')}
export async function documentLink(token:string,id:string){return json<{url:string;expires_at:number}>(await fetch(`${API}/documents/history/${id}/link`,{method:'POST',headers:mutationHeaders(token)}),'Lien indisponible')}
export async function printReceipt(token:string,paymentId:string,format?:'A5'|'80MM'):Promise<Blob>{const r=await fetch(`${API}/finance/checkout/receipts/${paymentId}/print${format?qp({format}):''}`,{method:'POST',headers:mutationHeaders(token)});if(!r.ok)throw new UserFacingError(await serverDetail(r,'Impression impossible'));return r.blob()}
export async function printBasketReceipts(token:string,basketId:string,format?:'A5'|'80MM'):Promise<Blob>{const r=await fetch(`${API}/finance/checkout/family-baskets/${basketId}/receipts/print${format?qp({format}):''}`,{method:'POST',headers:mutationHeaders(token)});if(!r.ok)throw new UserFacingError(await serverDetail(r,'Impression impossible'));return r.blob()}
export async function getPrintSettings(token:string){return json<PrintSettings>(await fetch(`${API}/finance/checkout/print-settings`,{headers:auth(token)}),'Réglages indisponibles')}
export async function putPrintSettings(token:string,body:{receipt_policy:PrintSettings['receipt_policy'];receipt_format:PrintSettings['receipt_format']}){return json<PrintSettings>(await fetch(`${API}/finance/checkout/print-settings`,{method:'PUT',headers:mutationHeaders(token),body:JSON.stringify(body)}),'Enregistrement impossible')}
export async function familyCollect(token:string,body:{family_id:string;lines:BasketLineInput[]},key:string){return json<BasketResult>(await fetch(`${API}/finance/checkout/family-collect`,{method:'POST',headers:{...auth(token),'Idempotency-Key':key},body:JSON.stringify(body)}),'Encaissement du panier refusé')}

// ---- Atelier Pro: platform team governance (N1) ----
export type PlatformMe={user:{id:string;email:string;full_name:string};roles:{code:string;label:string;kind:string}[];permissions:string[];menu:{key:string;label:string;capability:string}[];active_managers?:number|null;recommended_managers?:number};
export type PlatformCapability={code:string;label:string;group_name:string;risk:string;reserved:boolean;reserved_reason:string|null;held:boolean;delegable:boolean};
export type PlatformRole={id:string;code:string;label:string;description:string;kind:'PLATFORM_STANDARD'|'PLATFORM_CUSTOM';status:'DRAFT'|'OWNER_APPROVED'|'ACTIVE'|'ARCHIVED';version:number;updated_at:string;archived_at:string|null;capabilities:string[];active_users:number};
export type PlatformTeamUser={id:string;email:string;full_name:string;account_active:boolean;platform_status:'ACTIVE'|'SUSPENDED';roles:string[];last_activity:string|null;open_sessions:number;created_at:string;is_me:boolean;mfa_enrolled?:boolean};
export type PlatformTeamUserDetail=Omit<PlatformTeamUser,'roles'|'last_activity'|'open_sessions'>&{status_reason:string|null;status_changed_at:string|null;roles:{code:string;label:string;kind:string;status:string;active:boolean;created_at:string;reason:string|null}[];effective_permissions:string[];sessions:{id:string;label:string|null;created_at:string;last_seen_at:string}[];audit:{occurred_at:string;action:string;reason:string|null;actor:string|null}[];mfa?:{enrolled:boolean;confirmed_at:string|null;recovery_codes_remaining:number}};
const T=`${API}/platform/team`;
async function teamPost<R=any>(token:string,path:string,body:unknown,fallback:string):Promise<R>{return json<R>(await fetch(`${T}${path}`,{method:'POST',headers:mutationHeaders(token),body:JSON.stringify(body)}),fallback)}
export async function platformMe(token:string){return json<PlatformMe>(await fetch(`${T}/me`,{headers:auth(token)}),'Profil Atelier Pro indisponible')}
export async function teamCapabilities(token:string){return json<{items:PlatformCapability[]}>(await fetch(`${T}/capabilities`,{headers:auth(token)}),'Capacités indisponibles')}
export async function teamRoles(token:string){return json<{items:PlatformRole[]}>(await fetch(`${T}/roles`,{headers:auth(token)}),'Rôles indisponibles')}
export async function teamUsers(token:string,q=''){return json<{items:PlatformTeamUser[]}>(await fetch(`${T}/users${qp({q:q||undefined})}`,{headers:auth(token)}),'Équipe indisponible')}
export async function teamUser(token:string,id:string){return json<PlatformTeamUserDetail>(await fetch(`${T}/users/${id}`,{headers:auth(token)}),'Compte indisponible')}
export async function teamCreateRole(token:string,input:{code:string;label:string;description:string;capabilities:string[]}){return teamPost(token,'/roles',input,'Création du rôle impossible')}
export async function teamUpdateRole(token:string,id:string,input:{label:string;description:string;capabilities:string[];version:number}){return json<any>(await fetch(`${T}/roles/${id}`,{method:'PUT',headers:mutationHeaders(token),body:JSON.stringify(input)}),'Modification du rôle impossible')}
export async function teamRoleStatus(token:string,id:string,action:'activate'|'archive',reason:string){return teamPost(token,`/roles/${id}/${action}`,{reason},'Changement de statut impossible')}
export async function teamCloneRole(token:string,id:string,input:{code:string;label:string}){return teamPost(token,`/roles/${id}/clone`,input,'Clonage impossible')}
export async function teamCreateUser(token:string,input:{email:string;full_name:string;password:string;role_codes:string[];reason:string}){return teamPost(token,'/users',input,'Création du compte impossible')}
export async function teamAssignRole(token:string,id:string,role_code:string,reason:string){return teamPost(token,`/users/${id}/roles`,{role_code,reason},'Attribution impossible')}
export async function teamRevokeRole(token:string,id:string,role_code:string,reason:string){return teamPost(token,`/users/${id}/roles/${encodeURIComponent(role_code)}/revoke`,{reason},'Retrait impossible')}
export async function teamUserStatus(token:string,id:string,action:'suspend'|'reactivate',reason:string){return teamPost(token,`/users/${id}/${action}`,{reason},'Changement de statut impossible')}
export async function teamRevokeSessions(token:string,id:string,reason:string,sessionId?:string){return teamPost(token,sessionId?`/users/${id}/sessions/${sessionId}/revoke`:`/users/${id}/sessions/revoke-all`,{reason},'Déconnexion impossible')}
export async function teamResetPassword(token:string,id:string,new_password:string,reason:string){return teamPost(token,`/users/${id}/password-reset`,{new_password,reason},'Réinitialisation impossible')}
export async function teamResetMfa(token:string,id:string,reason:string,new_password?:string){return teamPost(token,`/users/${id}/mfa-reset`,{reason,...(new_password?{new_password}:{})},'Réinitialisation de la validation en deux étapes impossible')}

export type HealthComponent={key:string;label:string;state:'OK'|'DEGRADED'|'DOWN'|'NOT_CONFIGURED';detail:string;measured_ms?:number|null;age_seconds?:number|null;value?:number|null};
export type SystemHealth={checked_at:string;overall:'OK'|'DEGRADED'|'DOWN';components:HealthComponent[];figures:{schools_active?:number;sessions_open?:number}};
export async function systemHealth(token:string){return json<SystemHealth>(await fetch(`${API}/platform/system/health`,{headers:auth(token),cache:'no-store'}),'Santé du système indisponible')}

export type AuditFilters={q:string;action:string;scope:string;school:string;actor:string;result:string;date_from:string;date_to:string};
export type AuditRow={id:string;occurred_at:string;school_id:string|null;school_code:string|null;school_name:string|null;actor_user_id:string|null;actor:string|null;action:string;entity_type:string;entity_id:string|null;source:string;result:string;reason:string|null;correlation_id:string|null;has_changes:boolean};
function auditQuery(f:AuditFilters,extra:Record<string,string|undefined>={}){return qp({...Object.fromEntries(Object.entries(f).map(([k,v])=>[k,v||undefined])),...extra})}
export async function auditLog(token:string,f:AuditFilters,cursor:{at:string;id:string}|null){return json<{items:AuditRow[];has_more:boolean;actions:string[];next_cursor:{at:string;id:string}|null}>(await fetch(`${API}/platform/audit-log${auditQuery(f,{limit:'50',cursor_at:cursor?.at,cursor_id:cursor?.id})}`,{headers:auth(token)}),'Audit indisponible')}
export async function auditEvent(token:string,id:string){return json<any>(await fetch(`${API}/platform/audit-log/${id}`,{headers:auth(token)}),'Événement indisponible')}
export async function auditExport(token:string,f:AuditFilters){const r=await fetch(`${API}/platform/audit-log/export.csv${auditQuery(f)}`,{headers:auth(token)});if(!r.ok)throw new UserFacingError(await serverDetail(r,'Export impossible'));return r.blob()}

// ---- Notification center & campaigns (N1) ----
export type InboxScope='school'|'platform';
export type InboxItem={id:string;category:string;severity:'INFO'|'WARNING'|'CRITICAL';title:string;body:string;link_path:string|null;created_at:string;read_at:string|null;expires_at:string|null};
function inboxBase(scope:InboxScope){return scope==='platform'?`${API}/platform/inbox`:`${API}/notifications/inbox`}
export async function inboxList(token:string,scope:InboxScope,o:{status:string;severity:string;cursor:{at:string;id:string}|null;limit?:number}){return json<{items:InboxItem[];unread:number;next_cursor:{at:string;id:string}|null}>(await fetch(`${inboxBase(scope)}${qp({status:o.status==='all'?undefined:o.status,severity:o.severity||undefined,limit:o.limit??30,cursor_at:o.cursor?.at,cursor_id:o.cursor?.id})}`,{headers:auth(token),cache:'no-store'}),'Notifications indisponibles')}
export async function inboxRead(token:string,scope:InboxScope,id:string){if(scope==='platform')return json<any>(await fetch(`${API}/platform/inbox/${id}/read`,{method:'POST',headers:mutationHeaders(token)}),'Action impossible');return dismissNotification(token,id)}
export async function inboxReadAll(token:string,scope:InboxScope){return json<{marked_read:number}>(await fetch(`${inboxBase(scope)}/read-all`,{method:'POST',headers:mutationHeaders(token)}),'Action impossible')}
export type CampaignTarget={type:'ALL_ACTIVE_SCHOOLS'|'SCHOOLS'|'SCHOOL_ROLE'|'SCHOOL_USER'|'PLATFORM_ALL'|'PLATFORM_ROLE'|'PLATFORM_USER';school_ids:string[];role_code:string|null;user_id:string|null};
export type Campaign={id:string;title:string;severity:string;target_scope:string;target_json:any;link_path:string|null;expires_at:string|null;created_at:string;recipient_count:number;read_count:number;author:string|null;target_school_code:string|null};
export async function campaignList(token:string,offset=0){return json<{items:Campaign[];has_more:boolean}>(await fetch(`${API}/platform/notification-campaigns${qp({offset,limit:30})}`,{headers:auth(token)}),'Notifications indisponibles')}
export async function campaignSend(token:string,key:string,input:{title:string;body:string;severity:string;target:CampaignTarget;link_path:string|null;expires_at:string|null}){return json<{id:string;recipient_count:number;push?:{provider:string;devices:number;accepted:number}}>(await fetch(`${API}/platform/notification-campaigns`,{method:'POST',headers:{...auth(token),'Idempotency-Key':key},body:JSON.stringify(input)}),'Envoi impossible')}

export async function createSchoolFull(token:string,key:string,input:{name:string;code:string;email:string|null;phone:string|null;address:string|null;city:string|null;province:string|null}){return json<School&{address?:string|null;city?:string|null;province?:string|null}>(await fetch(`${API}/platform/schools`,{method:'POST',headers:{...auth(token),'Idempotency-Key':key},body:JSON.stringify(input)}),'Création de l’école impossible')}
